/* NEO AI — nav.research dictionary extension.

   Adds ONE key, `nav.research`, to the existing 18-language dictionary so the
   new Research link in the landing navigation is translated like every other
   nav item.

   Why a separate file rather than an edit to app-i18n.min.js: that file is
   362 KB, carries all eighteen dictionaries, and is under the v17.2 regression
   lock. Mutating one property of the existing `I18N` object achieves the same
   result with no edit to a locked artefact and no merge risk on the next
   translation pass.

   LOAD ORDER IS LOAD-BEARING. This file must be placed AFTER
   app-i18n.min.js (which declares `const I18N`) and BEFORE
   app-runtime.min.js (which reads it). Both are `defer`, so document order
   is execution order. See MODIFICATIONS.md, change M-03.

   Failure mode if the order is wrong or the file is absent: applyLang() does
   `if(dict[k])el.innerHTML=dict[k]`, so a missing key leaves the markup text
   untouched and the link reads "Research" in every language. Degraded, not
   broken. */
(function () {
  'use strict';
  if (typeof I18N === 'undefined' || !I18N || typeof I18N !== 'object') return;
  var T = {
    en: 'Research', fr: 'Recherche', it: 'Ricerca', es: 'Investigación',
    pt: 'Pesquisa', ru: 'Исследования', zh: '研究', ja: 'リサーチ',
    ko: '리서치', ar: 'الأبحاث', de: 'Forschung', hi: 'अनुसंधान',
    tr: 'Araştırma', th: 'งานวิจัย', vi: 'Nghiên cứu', bn: 'গবেষণা',
    id: 'Riset', ur: 'تحقیق'
  };
  for (var code in T) {
    if (!Object.prototype.hasOwnProperty.call(T, code)) continue;
    if (!I18N[code]) I18N[code] = {};
    I18N[code]['nav.research'] = T[code];
  }
})();
